function applyRS(n){RS=n;LBG.vn=null;cv.width=VW*RS;cv.height=VH*RS;x.setTransform(RS,0,0,RS,0,0);for(const k in BGC)delete BGC[k];MAPBG=null;HHC.k=''}
// 窗口模式:画面宽度取 640 的整数倍(按物理像素算),像素才不会忽大忽小。1080p 显示器上默认 1280 宽(2 倍);
// 窗口太小放不下 2 倍时,退回按窗口大小自适应。全屏仍然铺满(由 CSS 的 body.fs 规则控制)
function fitWrap(){const R_=document.documentElement.style;if(!matchMedia('(pointer:fine)').matches||document.fullscreenElement){R_.removeProperty('--ww');return}
  const d=window.devicePixelRatio||1,a=Math.min(innerWidth*.98,(innerHeight-74)*16/9,1920)*d,k=Math.floor(a/640);
  R_.setProperty('--ww',(k>=2?k*640/d:Math.max(320,Math.floor(a/d)))+'px')}
function uiScale(){fitWrap();const w=$('wrap').getBoundingClientRect().width,fine=matchMedia('(pointer:fine)').matches,R_=document.documentElement.style;
  const z=fine?Math.max(1,Math.min(2.2,w/860)):1;R_.setProperty('--uiz',z.toFixed(3));if(fine)R_.setProperty('--ph',($('c').getBoundingClientRect().height/z).toFixed(1)+'px');R_.setProperty('--tbz',fine?Math.max(1,Math.min(1.9,w/1000)).toFixed(3):1);}
addEventListener('resize',uiScale);
function setFsCls(){document.body.classList.toggle('fs',!!document.fullscreenElement)}
document.addEventListener('fullscreenchange',()=>{setFsCls();setTimeout(uiScale,50);if(pn=='set')renderP()});
